 * (feed/eval/gold-benchmark/labeling/app.js). Same sandbox technique as
 * pipeline/test/eval/h-bench-01-labeling-export.test.ts: app.js is a
 * plain <script> with a CommonJS export guard and no DOM access in its pure
 * functions, so we evaluate it in an isolated node:vm context (no
 * `document` global, so the browser-boot branch stays dormant) and exercise
 * the real exported functions.
 */
import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import vm from 'node:vm';
import { describe, expect, it } from 'vitest';

const here = dirname(fileURLToPath(import.meta.url));
const appPath = resolve(here, '../eval/gold-benchmark/labeling/app.js');

interface PanelApp {
  labelKey: (queryId: string, chunkRef: string) => string;
  parsePoolJsonl: (raw: string) => Array<Record<string, unknown>>;
  parseLabelsJsonl: (raw: string) => Map<string, Record<string, unknown>>;
  mergeLabelRows: (existing: Map<string, unknown>, incoming: unknown[]) => Map<string, unknown>;
  exportLabelsJsonl: (labels: Map<string, unknown>) => string;
  buildLabelRecord: (queryId: string, chunkRef: string, grade: 0 | 1 | 2) => Record<string, unknown>;
}

function loadPanelApp(): PanelApp {
  const source = readFileSync(appPath, 'utf-8');
  const sandboxModule = { exports: {} as Record<string, unknown> };
  // No `document` global in this sandbox, so the browser-boot IIFE never
  // runs and only the pure functions at the top of the file are defined.
  const context = vm.createContext({ module: sandboxModule });
  vm.runInContext(source, context, { filename: 'app.js' });
  return sandboxModule.exports as unknown as PanelApp;
}

